skin.css:
:root {
  --tb-glass: rgba(18, 18, 20, 0.26);
  --tb-hi: rgba(255, 255, 255, 0.12);
  --tb-hi-2: rgba(255, 255, 255, 0.22);
  --tb-line: rgba(255, 255, 255, 0.24);
  --tb-text: #ffffff;
  --tb-muted: rgba(255, 255, 255, 0.84);
  --tb-solid: #ffffff;
  --tb-solid-hi: #f1f1f2;
  --tb-ink: #0d0d0f;
  --tb-ease: cubic-bezier(0.2, 0.8, 0.2, 1);

  --tb-font: "Poppins", "Segoe UI", system-ui, -apple-system, Roboto, Arial, sans-serif;
}

.tour-skin { font-family: var(--tb-font); color: var(--tb-text); }

.tb-bar {
  position: absolute;
  left: 50%;
  bottom: 22px;
  bottom: max(22px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  max-width: calc(100vw - 32px);
  padding: 8px;
  background-color: var(--tb-glass);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.03) 55%, rgba(255, 255, 255, 0.06));
  border: 1px solid var(--tb-line);
  border-radius: 999px;
  -webkit-backdrop-filter: blur(7px) saturate(1.7) brightness(0.92);
  backdrop-filter: blur(7px) saturate(1.7) brightness(0.92);
  box-shadow:
    0 22px 50px -18px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.38),
    inset 0 -1px 0 rgba(255, 255, 255, 0.08);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
  pointer-events: auto;
  animation: tb-rise 0.7s var(--tb-ease) 0.2s both;
}
@keyframes tb-rise {
  from { opacity: 0; transform: translate(-50%, 26px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.tb-btn {
  appearance: none;
  -webkit-appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 56px;
  padding: 0 22px;
  border: 0;
  border-radius: 999px;
  background-color: var(--tb-hi);
  color: var(--tb-text);
  font: 600 17px/1 var(--tb-font);
  letter-spacing: 0.01em;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.2s, color 0.2s, box-shadow 0.25s var(--tb-ease), transform 0.25s var(--tb-ease);
}
.tb-btn:hover { background-color: var(--tb-hi-2); transform: translateY(-1px); }
.tb-btn:active { transform: translateY(0) scale(0.96); transition-duration: 0.08s; }
.tb-btn:focus-visible { outline: 3px solid var(--tb-solid); outline-offset: 3px; }
.tb-btn svg { width: 20px; height: 20px; flex: none; transition: transform 0.3s var(--tb-ease); }

@media (max-width: 560px) {
  .tb-bar { bottom: 14px; gap: 4px; padding: 6px; }
  .tb-btn { min-height: 52px; padding: 0 16px; font-size: 16px; }
  .tb-btn .tb-label { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .tb-bar, .tb-btn, .tb-btn svg { animation: none !important; transition: none !important; }
}

.tb-prev { padding-left: 16px; }
.tb-prev:hover svg { transform: translateX(-3px); }

.tb-next { padding-right: 16px; background-color: var(--tb-solid); color: var(--tb-ink); text-shadow: none; }
.tb-next:hover { background-color: var(--tb-solid); box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.18), 0 8px 22px -8px rgba(0, 0, 0, 0.5); }
.tb-next:hover svg { transform: translateX(3px); }

.tp-vr:not([hidden]):not(.on) {
  top: 50%; right: auto; left: 50%;
  transform: translate(-50%, -50%);
  z-index: 30;
  min-height: 88px;
  padding: 0 38px 0 30px;
  gap: 14px;
  border-radius: 999px;
  font: 600 26px/1 var(--tb-font);
  color: var(--tb-ink);
  background-color: var(--tb-solid);
  box-shadow: 0 22px 50px -12px rgba(0, 0, 0, 0.65);
  animation: tb-vr-pulse 2.2s ease-out infinite;
}
.tp-vr:not([hidden]):not(.on):hover { background-color: var(--tb-solid-hi); }
.tp-vr:not([hidden]):not(.on):active { transform: translate(-50%, -50%) scale(0.96); }
.tp-vr:not(.on) svg { width: 36px; height: 36px; }
.tp-vr:not(.on) span { font-size: 0; }
.tp-vr:not(.on) span::after { content: "Enter VR"; font-size: 26px; }
@keyframes tb-vr-pulse {
  0% { box-shadow: 0 22px 50px -12px rgba(0, 0, 0, 0.65), 0 0 0 0 rgba(255, 255, 255, 0.55); }
  100% { box-shadow: 0 22px 50px -12px rgba(0, 0, 0, 0.65), 0 0 0 30px rgba(255, 255, 255, 0); }
}

.tb-crumbs { --tb-brand: #e9b872; --tb-brand-hi: #f2c98c; --tb-brand-ink: #1f1609;
  display: flex; align-items: center; gap: 2px; padding: 0 4px; min-width: 0; }
.tb-crumb {
  display: inline-flex; align-items: center; gap: 9px;
  min-height: 44px; padding: 0 16px;
  border-radius: 999px;
  color: var(--tb-muted); text-decoration: none;
  font: 500 15px/1 var(--tb-font); white-space: nowrap;
  transition: background-color 0.35s var(--tb-ease), color 0.35s, box-shadow 0.35s;
}
.tb-crumb:hover { color: var(--tb-text); background-color: var(--tb-hi); }
.tb-dot { width: 7px; height: 7px; border-radius: 50%; background-color: rgba(255, 255, 255, 0.6); flex: none; transition: background-color 0.35s; }
.tb-crumb[data-tour-current] {
  background-color: var(--tb-brand); color: var(--tb-brand-ink); font-weight: 600; text-shadow: none;
  box-shadow: 0 8px 22px -8px rgba(233, 184, 114, 0.7);
}
.tb-crumb[data-tour-current]:hover { background-color: var(--tb-brand-hi); }
.tb-crumb[data-tour-current] .tb-dot { background-color: var(--tb-brand-ink); }

@media (max-width: 1000px) {
  .tb-crumb { padding: 0 13px; }
  .tb-crumb .tb-crumb-name { display: none; }
  .tb-crumb[data-tour-current] { padding: 0 16px; }
  .tb-crumb[data-tour-current] .tb-crumb-name { display: inline; }
}

@media (max-width: 480px) {
  .tb-crumb:not([data-tour-current]) { display: none; }
}

.tb-tips {
  position: absolute; left: 50%; bottom: 102px;
  transform: translateX(-50%);
  display: flex; justify-content: space-between; align-items: flex-end;
  pointer-events: none;

  animation: tb-tip-in 0.5s var(--tb-ease) 1.1s both, tb-bob 2.6s ease-in-out 1.6s infinite;
}
.tb-tip { display: flex; flex-direction: column; }
.tb-tip-prev { align-items: flex-start; }
.tb-tip-next { align-items: flex-end; }
.tb-tip-box {
  display: block;
  padding: 10px 15px;
  border-radius: 12px;
  background-color: var(--tb-solid); color: var(--tb-ink);
  font: 600 14px/1 var(--tb-font); white-space: nowrap;
  box-shadow: 0 10px 26px -10px rgba(0, 0, 0, 0.6);
}
.tb-tip-point { display: flex; color: var(--tb-solid); }
.tb-tip-next .tb-tip-point { justify-content: flex-end; }
.tb-tip-arrow { display: block; width: 16px; height: 8px; margin-top: -1px; }
.tb-tips.is-leaving { animation: tb-tip-out 0.45s var(--tb-ease) forwards; }
.tb-tips.is-done { visibility: hidden; animation: none; }
@keyframes tb-tip-in { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }
@keyframes tb-tip-out { from { opacity: 1; transform: translate(-50%, 0); } to { opacity: 0; transform: translate(-50%, 6px); } }
@keyframes tb-bob { 0%, 100% { transform: translate(-50%, 0); } 50% { transform: translate(-50%, -5px); } }
@media (max-width: 560px) { .tb-tips { bottom: 84px; } .tb-tip-box { font-size: 13px; padding: 8px 12px; } }
@media (prefers-reduced-motion: reduce) { .tb-tips { animation: none !important; } }
